mapper.select:
SELECT d.id dependencyId,d.target_type targetType,d.target_id targetId,d.review_status status,
 d.source_document_id documentId,d.source_version_id documentVersionId,doc.title documentTitle,
 d.detected_at detectedAt,d.confirmed_by confirmedBy,d.confirmed_at confirmedAt,d.note
FROM sa_content_dependency d JOIN sa_document doc ON doc.id=d.source_document_id
WHERE d.project_id=#{projectId} AND d.review_status=#{status}
AND d.target_type=#{targetType}
AND d.source_document_id=#{documentId}
ORDER BY d.detected_at DESC,d.id DESC
